const DAILY_QUESTION_LIMIT = 20;
async function refreshDailyQuota(){
  const nodes=[...document.querySelectorAll('[data-daily-quota]')];
  if(!nodes.length)return;
  try{
    const{data,error}=await sb.rpc('get_daily_question_usage');if(error)throw error;
    const row=Array.isArray(data)?data[0]:data;const used=Number(row?.used)||0;const remaining=Number(row?.remaining??(DAILY_QUESTION_LIMIT-used));
    nodes.forEach(el=>{el.textContent=`${used}/${DAILY_QUESTION_LIMIT}`;el.setAttribute('aria-label',`${remaining} questions remaining today`)});
    document.querySelectorAll('[data-quota-remaining]').forEach(el=>el.textContent=String(remaining));
    document.querySelectorAll('[data-quota-fill]').forEach(el=>el.style.width=`${Math.min(100,used/DAILY_QUESTION_LIMIT*100)}%`);
  }catch{nodes.forEach(el=>{el.textContent='—';el.setAttribute('aria-label','Daily question usage unavailable')})}
}
async function consumeDailyQuestion(){
  const{data,error}=await sb.rpc('consume_daily_question');if(error)throw new Error('Could not verify the daily question limit. Please try again.');
  const row=Array.isArray(data)?data[0]:data;await refreshDailyQuota();
  if(!row?.allowed)throw new Error('You have used all 20 questions for today. Your daily limit resets at midnight Riyadh time.');
  return row;
}
async function getDailyQuestionRemaining(){const{data,error}=await sb.rpc('get_daily_question_usage');if(error)throw new Error('Could not check your daily allowance. Please try again.');const row=Array.isArray(data)?data[0]:data;await refreshDailyQuota();return Number(row?.remaining??20)}
async function releaseDailyQuestion(reservationId){if(!reservationId)return;try{await sb.rpc('release_daily_question',{p_reservation_id:reservationId})}finally{await refreshDailyQuota()}}
