async function loadHomeOverview(){
 const avg=document.querySelector('#overviewQuizAvg');if(!avg)return;
 const set=(id,value)=>{const el=document.querySelector(id);if(el)el.textContent=value};
 try{
  const{data:{session}}=await sb.auth.getSession();const user=session?.user;
  if(!user||user.is_anonymous){set('#overviewQuizAvg','—');set('#overviewQuizSub','Sign in to save quiz history');set('#overviewPaperAvg','—');set('#overviewPaperSub','Sign in to view paper results');set('#overviewTasks','—');set('#overviewTasksSub','Sign in to save revision tasks');return}
  const results=await Promise.allSettled([
   sb.from('quiz_attempts').select('percentage,topic_results,created_at').eq('student_id',user.id).order('created_at',{ascending:false}).limit(30),
   sb.from('paper_checks').select('marks_awarded,marks_total,percentage,created_at').eq('student_id',user.id).order('created_at',{ascending:false}).limit(30),
   sb.from('revision_tasks').select('id,completed_at,title,topic,reason,priority').eq('user_id',user.id).order('completed_at',{ascending:true,nullsFirst:true}).limit(8)
  ]);
  const quizzes=results[0].status==='fulfilled'&&!results[0].value.error?(results[0].value.data||[]):[];
  const papers=results[1].status==='fulfilled'&&!results[1].value.error?(results[1].value.data||[]):[];
  const tasks=results[2].status==='fulfilled'&&!results[2].value.error?(results[2].value.data||[]):[];
  const qavg=quizzes.length?Math.round(quizzes.reduce((n,r)=>n+(Number(r.percentage)||0),0)/quizzes.length):null;
  const valid=papers.filter(r=>Number(r.marks_total)>0&&Number.isFinite(Number(r.marks_awarded)));
  const pavg=valid.length?Math.round(valid.reduce((n,r)=>n+(Number(r.percentage)||Number(r.marks_awarded)/Number(r.marks_total)*100),0)/valid.length):null;
  set('#overviewQuizAvg',qavg===null?'—':qavg+'%');set('#overviewQuizSub',quizzes.length+' saved attempt'+(quizzes.length===1?'':'s'));
  set('#overviewPaperAvg',pavg===null?'—':pavg+'%');set('#overviewPaperSub',valid.length+' valid marked result'+(valid.length===1?'':'s'));
  const open=tasks.filter(t=>!t.completed_at);set('#overviewTasks',String(open.length));set('#overviewTasksSub',tasks.length+' saved revision task'+(tasks.length===1?'':'s'));
  const topicMap=new Map();for(const quiz of quizzes)for(const t of (Array.isArray(quiz.topic_results)?quiz.topic_results:[])){const x=topicMap.get(t.label)||{label:t.label,ok:0,total:0};x.ok+=Number(t.ok)||0;x.total+=Number(t.total)||0;topicMap.set(t.label,x)}
  const topics=[...topicMap.values()].filter(t=>t.total).map(t=>({...t,pct:Math.round(t.ok/t.total*100)})).sort((a,b)=>a.pct-b.pct);
  const focus=document.querySelector('#overviewTopicFocus');if(focus){focus.innerHTML=topics.length?topics.slice(0,3).map(t=>`<div class="overview-topic-row"><span>${escape(t.label)}</span><div class="overview-topic-track"><i style="width:${t.pct}%"></i></div><b>${t.pct}%</b></div>`).join(''):'<span class="overview-placeholder">Complete a quiz to discover your strongest and weakest topics.</span>'}
  const revision=document.querySelector('#overviewRevisionFocus');if(revision){revision.innerHTML=open.length?open.slice(0,3).map(t=>`<div class="overview-task-row"><span class="overview-task-dot priority-${escape(t.priority||'medium')}"></span><span><b>${escape(t.title)}</b><small>${escape(t.topic||t.reason||'Physics revision')}</small></span></div>`).join(''):'<span class="overview-placeholder">No open tasks yet. Complete a quiz, then build your revision plan.</span>'}
 }catch{set('#overviewQuizSub','Progress data is temporarily unavailable')}
}
