function addSyImage(file){
  if(!imageFiles)imageFiles=[];
  imageFiles.push(file);
  const att=document.querySelector('#syAttachmentStatus');
  if(att){
    const chip=document.createElement('span');chip.className='sy-chip';
    const thumb=file.type.startsWith('image/')?URL.createObjectURL(file):'';
    chip.innerHTML=(thumb?`<img src="${thumb}" style="width:20px;height:20px;object-fit:cover;border-radius:4px" alt="">`:'')+'<span>'+escape(file.name)+'</span><button type="button" aria-label="Remove">×</button>';
    chip.querySelector('button').onclick=()=>{imageFiles=imageFiles.filter(f=>f!==file);chip.remove();URL.revokeObjectURL(thumb)};
    att.append(chip);
  }
  const st=document.querySelector('#syImageStatus');if(st)st.textContent=imageFiles.length+' image'+(imageFiles.length>1?'s':'')+' attached';
}
