async function uploadAsset(bucket,file,userId,label,contentType){const clean=(file.name||label).split(' ').join('-');const path=userId+'/ai-inputs/'+Date.now()+'-'+label+'-'+clean;const {error}=await sb.storage.from(bucket).upload(path,file,{contentType:contentType||file.type||'application/octet-stream',upsert:false});if(error)throw new Error(label+' upload failed: '+error.message);const {data,error:signError}=await sb.storage.from(bucket).createSignedUrl(path,3600);if(signError||!data?.signedUrl)throw new Error(label+' link creation failed: '+(signError?.message||'unknown error'));return data.signedUrl}
async function uploadPdfPages(file,userId,label,onProgress=()=>{}){const pages=await renderPdfPagesToImages(file,onProgress),urls=[];for(let i=0;i<pages.length;i++){onProgress('Uploading page image '+(i+1)+' of '+pages.length+'…');urls.push(await uploadAsset('answer-uploads',pages[i],userId,label+'-page-'+String(i+1).padStart(3,'0'),'image/jpeg'))}return urls}
async function withKB(q){try{const{data}=await sb.from('materials').select('title,content_text').not('content_text','is',null).limit(60);const words=new Set(String(q).toLowerCase().match(/[a-z]{4,}/g)||[]),ch=[];(data||[]).forEach(r=>r.content_text.split(/\n+/).flatMap(p=>p.match(/.{1,700}(\s|$)/g)||[]).forEach(p=>{const s=(p.toLowerCase().match(/[a-z]{4,}/g)||[]).filter(x=>words.has(x)).length;if(s>0)ch.push({t:r.title,p:p.trim(),s})}));ch.sort((a,b)=>b.s-a.s);let n=0;const use=ch.filter(c=>(n+=c.p.length)<6000);if(!use.length)return q;return 'Use the teacher knowledge base below when it covers the question, and name the material you used. If it does not cover it, answer from the official syllabus.\n\nKNOWLEDGE BASE:\n'+use.map(c=>'['+c.t+'] '+c.p).join('\n')+'\n\nSTUDENT QUESTION:\n'+q}catch{return q}}
async function aiModal(question,{imageUrl=null,audioUrl=null,pdfUrl=null,pdfFile=null,conversationHistory=[]}={}){question=await withKB(question);let pdfPageImageUrls=[];if(pdfFile&&((pdfFile.type||'')==='application/pdf'||/\.pdf$/i.test(pdfFile.name||''))){const{data:{user}}=await sb.auth.getUser();if(!user)throw new Error('Could not identify the signed-in user to process PDF pages.');pdfPageImageUrls=await uploadPdfPages(pdfFile,user.id,'tutor-question',msg=>{const status=document.querySelector('#syAttachmentStatus');if(status)status.textContent=msg})}const {data,error}=await sb.functions.invoke('ai-route',{body:{mode:'tutor',modality:imageUrl?'image':pdfPageImageUrls.length?'image':pdfUrl?'pdf':audioUrl?'audio':'text',question,imageUrl,audioUrl,pdfUrl,pdfPageImageUrls,conversationHistory}});if(error){let message=error.message||'AI service unavailable';try{const payload=await error.context?.json?.();message=[payload?.error,payload?.detail].filter(Boolean).join(': ')||message;const status=error.context?.status;if(status)message+=' (HTTP '+status+')'}catch{}throw new Error(message)}if(data?.error)throw new Error([data.error,data.detail].filter(Boolean).join(': ')||'AI service unavailable');return data}
